from __future__ import annotations
from typing import Sequence

def energy(w: Sequence[float], x: Sequence[float]) -> float:
    return 0.5 * sum(a*b*b for a, b in zip(w, x))

def run() -> None:
    w, x0, eta = [1.0, 100.0, 1_000_000.0], [3.0, -2.0, 0.01], 0.2
    x = list(x0); e0 = energy(w, x0)
    for k in range(9):
        exact = ((1.0-eta)**2)**k * e0
        print(k, energy(w, x), exact)
        assert abs(energy(w, x)-exact) <= 1e-9*max(1.0, exact)
        x = [(1.0-eta)*a for a in x]
if __name__ == "__main__": run()

